extra_head_css:
.rotate-workspace { display: flex; gap: 24px; flex-wrap: wrap; }
    .rotate-sidebar { flex: 0 0 280px; display: flex; flex-direction: column; gap: 16px; }
    .rotate-canvas-area { flex: 1; min-width: 300px; }

    .quick-actions { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
    .quick-btn {
      padding: 10px 8px; border: 2px solid var(--border); border-radius: 8px;
      background: var(--bg-primary); color: var(--text-primary); cursor: pointer;
      text-align: center; font-size: .85rem; transition: all .2s;
      display: flex; align-items: center; justify-content: center; gap: 6px;
    }
    .quick-btn:hover { border-color: var(--accent); background: rgba(99,102,241,.08); }
    .quick-btn:active { transform: scale(.96); }
    .quick-btn .btn-icon { font-size: 1.1rem; }

    .control-group { display: flex; flex-direction: column; gap: 6px; }
    .control-group label { font-size: .8rem; color: var(--text-secondary); font-weight: 500; }
    .control-group select, .control-group input[type="number"] {
      padding: 8px 10px; border: 1px solid var(--border); border-radius: 6px;
      background: var(--bg-primary); color: var(--text-primary); font-size: .85rem;
    }
    .control-group input[type="range"] { width: 100%; }
    .angle-display {
      text-align: center; font-size: 1.2rem; font-weight: 600;
      color: var(--accent); padding: 4px 0;
    }

    .canvas-wrapper {
      background: repeating-conic-gradient(var(--bg-secondary) 0% 25%, var(--bg-primary) 0% 50%) 50% / 20px 20px;
      border: 1px solid var(--border); border-radius: 12px; padding: 16px;
      display: flex; align-items: center; justify-content: center; min-height: 300px;
      overflow: auto;
    }
    .canvas-wrapper canvas { max-width: 100%; max-height: 500px; border-radius: 4px; }

    @media (max-width: 768px) {
      .rotate-workspace { flex-direction: column; }
      .rotate-sidebar { flex: none; width: 100%; }
    }
